-- Minimal stand-in for the production Supabase schema (owmsddezprhrjiinznmq), enough to apply and test the
-- admin migrations locally. Function bodies for the enrollment/payment triggers are copied from production.
create extension if not exists pgcrypto with schema public;
create schema if not exists extensions;
create or replace function extensions.gen_random_bytes(int) returns bytea language sql as $$ select public.gen_random_bytes($1) $$;
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then create role service_role nologin bypassrls; end if;
end $$;
create schema if not exists auth;
create table if not exists auth.users (id uuid primary key default gen_random_uuid(), email text);
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
create or replace function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb $$;
grant usage on schema auth to anon, authenticated, service_role;
grant execute on all functions in schema auth to anon, authenticated, service_role;
create schema if not exists private;
grant usage on schema private to authenticated, service_role;
create table if not exists private.counters (kind text, yr int, n int not null default 0, primary key (kind, yr));
create or replace function private.next_no(p_kind text, p_yr integer) returns integer language sql security definer set search_path to '' as $$
  insert into private.counters as c (kind, yr, n) values (p_kind, p_yr, 1) on conflict (kind, yr) do update set n = c.n + 1 returning n; $$;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text not null unique, full_name text, country text, phone text,
  role text not null default 'user', created_at timestamptz not null default now(), constraint profiles_role_check check (role = any (array['user','admin'])));
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path to '' as $$
  select exists(select 1 from public.profiles where id = (select auth.uid()) and role = 'admin'); $$;
create or replace function private.my_email() returns text language sql stable set search_path to '' as $$ select lower(coalesce((select auth.jwt()) ->> 'email', '')); $$;
create or replace function private.guard_profile() returns trigger language plpgsql set search_path to '' as $$
begin
  if new.role is distinct from old.role and not private.is_admin() and current_user = 'authenticated' then raise exception 'Only admins can change roles'; end if;
  new.id := old.id; new.created_at := old.created_at; return new;
end $$;
drop trigger if exists profiles_guard on public.profiles;
create trigger profiles_guard before update on public.profiles for each row execute function private.guard_profile();
create table if not exists public.courses (code text primary key, name text not null, level text not null, duration_days int not null check (duration_days > 0), active boolean not null default true, fee_pkr int, old_fee_pkr int, short_code text);
create table if not exists public.site_settings (key text primary key, value text not null, updated_at timestamptz not null default now());
create table if not exists public.enrollments (
  id bigint generated by default as identity primary key, email text not null check (position('@' in email) > 1), full_name text, course_code text references public.courses(code), course_label text,
  status text not null default 'pending' check (status = any (array['pending','active','expired','revoked'])), start_date date, end_date date, source text not null default 'form', source_ref text unique,
  created_at timestamptz not null default now(), activated_at timestamptz, activated_by uuid references auth.users(id) on delete set null, confirmation_sent_at timestamptz, welcome_sent_at timestamptz, notes text, receipt_url text,
  student_id text unique, batch_code text, invoice_no text unique, invoiced_at timestamptz, certificate_no text unique, certificate_code text unique, certificate_issued_at timestamptz, sheet_row int,
  certificate_hold boolean not null default false, certificate_revoked_at timestamptz, certificate_file text, admission_file text, receipt_file text, docs_error text, fee_total int, amount_paid int not null default 0,
  balance_due int generated always as (greatest(coalesce(fee_total,0) - coalesce(amount_paid,0), 0)) stored, payment_plan text not null default 'full' check (payment_plan = any (array['full','two','custom'])),
  due_date date, reminder_stage smallint not null default 0, last_docs_sent_at timestamptz, last_docs_sent_items text, phone text);
create table if not exists public.payments (id bigint generated by default as identity primary key, enrollment_id bigint not null references public.enrollments(id) on delete cascade, amount int not null check (amount > 0),
  paid_on date not null default ((now() at time zone 'Asia/Karachi')::date), proof_url text, invoice_no text unique, installment_no smallint not null default 1, installments smallint not null default 1, is_final boolean not null default false,
  receipt_file text, created_by uuid, created_at timestamptz not null default now(), installment_label text, method text check (method is null or method = any (array['cash','bank','jazzcash','easypaisa','other'])));
create table if not exists public.email_log (id bigint generated by default as identity primary key, enrollment_id bigint references public.enrollments(id) on delete set null, kind text not null, items text[] not null default '{}', to_email text, status text not null, error text, sent_by uuid, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.enrollments enable row level security; alter table public.payments enable row level security;
alter table public.email_log enable row level security; alter table public.courses enable row level security; alter table public.site_settings enable row level security;
drop policy if exists profiles_select on public.profiles; create policy profiles_select on public.profiles for select to authenticated using ((id = (select auth.uid())) or (select private.is_admin()));
drop policy if exists profiles_update on public.profiles; create policy profiles_update on public.profiles for update to authenticated using ((id = (select auth.uid())) or (select private.is_admin())) with check ((id = (select auth.uid())) or (select private.is_admin()));
drop policy if exists courses_read on public.courses; create policy courses_read on public.courses for select to anon, authenticated using (true);
drop policy if exists enr_select on public.enrollments; create policy enr_select on public.enrollments for select to authenticated using ((select private.is_admin()) or ((email = (select private.my_email())) and coalesce((((select auth.jwt()) ->> 'email_verified'))::boolean, true)));
drop policy if exists enr_admin_ins on public.enrollments; create policy enr_admin_ins on public.enrollments for insert to authenticated with check ((select private.is_admin()));
drop policy if exists enr_admin_upd on public.enrollments; create policy enr_admin_upd on public.enrollments for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
drop policy if exists enr_admin_del on public.enrollments; create policy enr_admin_del on public.enrollments for delete to authenticated using ((select private.is_admin()));
drop policy if exists pay_admin_select on public.payments; create policy pay_admin_select on public.payments for select to authenticated using ((select private.is_admin()));
drop policy if exists elog_admin_select on public.email_log; create policy elog_admin_select on public.email_log for select to authenticated using ((select private.is_admin()));
grant usage on schema public to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to authenticated, service_role;
-- like production: new tables get no automatic grants for anon/authenticated (migrations must grant what they need)
alter default privileges in schema public grant select, insert, update, delete on tables to service_role;
create or replace function private.enrollment_dates() returns trigger language plpgsql set search_path to '' as $$
declare d int;
begin
  new.email := lower(trim(new.email));
  if new.status = 'active' and (tg_op = 'INSERT' or old.status is distinct from 'active') then
    select duration_days into d from public.courses where code = new.course_code;
    if d is null then raise exception 'Pick a course for this enrollment before activating it'; end if;
    new.start_date := coalesce(new.start_date, (now() at time zone 'Asia/Karachi')::date); new.end_date := new.start_date + d + 15; new.activated_at := now(); new.activated_by := auth.uid();
  end if; return new;
end $$;
create or replace function private.enrollment_numbers() returns trigger language plpgsql security definer set search_path to '' as $$
declare k text; y int := extract(year from (now() at time zone 'Asia/Karachi'))::int; lv text;
begin
  if tg_op = 'UPDATE' then
    new.student_id := coalesce(old.student_id, new.student_id); new.invoice_no := coalesce(old.invoice_no, new.invoice_no); new.invoiced_at := coalesce(old.invoiced_at, new.invoiced_at);
    new.certificate_no := coalesce(old.certificate_no, new.certificate_no); new.certificate_code := coalesce(old.certificate_code, new.certificate_code); new.certificate_issued_at := coalesce(old.certificate_issued_at, new.certificate_issued_at);
  end if;
  if tg_op = 'INSERT' or new.student_id is null then
    if tg_op = 'INSERT' then new.student_id := null; new.invoice_no := null; new.certificate_no := null; new.certificate_code := null; end if;
    new.student_id := 'DFA-' || y || '-' || lpad(private.next_no('student', y)::text, 4, '0');
  end if;
  if new.course_code is not null and (tg_op = 'INSERT' or new.batch_code is null or new.course_code is distinct from old.course_code or new.start_date is distinct from old.start_date) then
    select short_code into k from public.courses where code = new.course_code;
    if k is not null then new.batch_code := k || '-' || to_char(coalesce(new.start_date, (coalesce(new.created_at, now()) at time zone 'Asia/Karachi')::date), 'YYMM'); end if;
  end if;
  if new.status = 'active' and new.invoice_no is null then new.invoice_no := 'INV-' || y || '-' || lpad(private.next_no('invoice', y)::text, 4, '0'); new.invoiced_at := now(); end if;
  if new.certificate_issued_at is not null and new.certificate_no is null then
    select upper(replace(level, '-', '')) into lv from public.courses where code = new.course_code; lv := coalesce(lv, 'GEN');
    new.certificate_no := 'DFA-' || lv || '-' || y || '-' || lpad(private.next_no('cert-' || lv, y)::text, 4, '0'); new.certificate_code := upper(substr(encode(extensions.gen_random_bytes(8), 'hex'), 1, 12));
  end if; return new;
end $$;
create or replace function private.payment_numbers() returns trigger language plpgsql security definer set search_path to '' as $$
declare y int := extract(year from (now() at time zone 'Asia/Karachi'))::int;
begin if new.invoice_no is null then new.invoice_no := 'INV-' || y || '-' || lpad(private.next_no('invoice', y)::text, 4, '0'); end if; return new; end $$;
drop trigger if exists enrollments_dates on public.enrollments; create trigger enrollments_dates before insert or update on public.enrollments for each row execute function private.enrollment_dates();
drop trigger if exists enrollments_numbers on public.enrollments; create trigger enrollments_numbers before insert or update on public.enrollments for each row execute function private.enrollment_numbers();
drop trigger if exists payments_numbers on public.payments; create trigger payments_numbers before insert on public.payments for each row execute function private.payment_numbers();
insert into public.courses (code, name, level, duration_days, fee_pkr, short_code) values ('a1-normal', 'A1 Normal', 'A1', 60, 25000, 'A1N'), ('b1', 'B1', 'B1', 75, 40000, 'B1') on conflict do nothing;
